{
  "missing_information": [
    {
      "category": "Trigger Conditions",
      "gap": "No information on what initiates a sample transfer request (e.g., scheduled evaluation, ad-hoc request, downstream process signal)",
      "why_it_matters": "Without knowing the trigger, it is impossible to determine where the process starts or whether initiation can be automated"
    },
    {
      "category": "Roles and Responsibilities",
      "gap": "The actors involved in each step (who requests, who approves, who physically moves, who evaluates) are not defined",
      "why_it_matters": "Role clarity is required to map handoffs, identify bottlenecks, and assess which steps could be automated or reassigned"
    },
    {
      "category": "Evaluation Criteria",
      "gap": "The criteria used to classify a sample as 'unnecessary' after evaluation are not specified",
      "why_it_matters": "Without defined criteria, the decision point between retention and disposal cannot be modeled or automated"
    },
    {
      "category": "Disposal Request Process",
      "gap": "The steps, approvals, and systems involved in the disposal request are not described",
      "why_it_matters": "The disposal sub-process may have compliance, safety, or regulatory requirements that affect automation feasibility and audit trail needs"
    },
    {
      "category": "System Integration",
      "gap": "No information on which systems (e.g., inventory, lab management, tracking) are used to record or manage transfers and disposal requests",
      "why_it_matters": "System touchpoints determine where data is captured and where automation or integration can be applied"
    },
    {
      "category": "Exception Handling",
      "gap": "No information on what happens when a sample is lost, damaged, or fails evaluation in an unexpected way",
      "why_it_matters": "Exception paths are often the source of process delays and manual workarounds that are prime candidates for automation"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What event or condition triggers the initiation of a wafer sample transfer — for example, is it a scheduled evaluation cycle, a manual request from an engineer, or a signal from an upstream process step?",
      "targets": ["Trigger Conditions"]
    },
    {
      "id": "Q2",
      "question": "Who are the specific roles involved at each stage of the workflow — such as who submits the transfer request, who authorizes it, who performs the physical transfer, and who conducts the evaluation?",
      "targets": ["Roles and Responsibilities"]
    },
    {
      "id": "Q3",
      "question": "What specific criteria or rules determine whether a sample is classified as 'unnecessary' and eligible for disposal after evaluation?",
      "targets": ["Evaluation Criteria"]
    },
    {
      "id": "Q4",
      "question": "Can you walk through the individual steps of the disposal request process, including any approvals required, the parties who must sign off, and any regulatory or safety compliance checks that must be completed?",
      "targets": ["Disposal Request Process"]
    },
    {
      "id": "Q5",
      "question": "Which systems or tools are used to record and track sample transfers and disposal requests throughout the workflow — for example, a lab information management system, an inventory database, or a manual log?",
      "targets": ["System Integration"]
    },
    {
      "id": "Q6",
      "question": "How is the process handled when a sample is damaged, goes missing during transfer, or produces an inconclusive evaluation result — is there a defined escalation or rework path?",
      "targets": ["Exception Handling"]
    }
  ]
}
